import{az as s,P as n,Q as e,aQ as l}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const D=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"server/attack/index.md","filePath":"server/attack/index.md","lastUpdated":1785339991000}'),t={name:"server/attack/index.md"};function o(p,a,r,c,i,d){return n(),e("div",null,[...a[0]||(a[0]=[l(`<h2 id="web-安全攻击概述" tabindex="-1">Web 安全攻击概述 <a class="header-anchor" href="#web-安全攻击概述" aria-label="Permalink to “Web 安全攻击概述”">​</a></h2><p><a href="https://owasp.org/www-project-top-ten/" target="_blank" rel="noreferrer">OWASP Top 10</a></p><p>Web 安全是保护 Web 应用程序免受恶意攻击的实践。攻击者利用应用程序的漏洞窃取数据、破坏服务或欺骗用户。了解常见攻击方式是构建安全应用的前提。</p><h2 id="攻击分类" tabindex="-1">攻击分类 <a class="header-anchor" href="#攻击分类" aria-label="Permalink to “攻击分类”">​</a></h2><p>Web 安全威胁可按攻击目标与手段分为以下几类：</p><table tabindex="0"><thead><tr><th>类别</th><th>代表攻击</th><th>核心问题</th></tr></thead><tbody><tr><td>注入类</td><td>SQL 注入、XSS</td><td>未对输入进行过滤与转义</td></tr><tr><td>伪造类</td><td>CSRF、点击劫持</td><td>借助用户身份发起未授权操作</td></tr><tr><td>拒绝服务类</td><td>DDoS</td><td>耗尽服务器资源使其不可用</td></tr><tr><td>认证授权类</td><td>会话固定、越权访问</td><td>身份校验与权限控制缺陷</td></tr><tr><td>配置类</td><td>目录遍历、信息泄露</td><td>服务器配置不当</td></tr></tbody></table><h2 id="常见攻击方式简介" tabindex="-1">常见攻击方式简介 <a class="header-anchor" href="#常见攻击方式简介" aria-label="Permalink to “常见攻击方式简介”">​</a></h2><h3 id="跨站脚本攻击-xss" tabindex="-1">跨站脚本攻击（XSS） <a class="header-anchor" href="#跨站脚本攻击-xss" aria-label="Permalink to “跨站脚本攻击（XSS）”">​</a></h3><p>攻击者将恶意脚本注入到网页中，在其他用户浏览器中执行，可窃取 Cookie 或会话信息。</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;">// 危险：直接拼接用户输入</span></span>
<span class="line"><span style="color:#BABED8;">element</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">innerHTML </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> userInput</span><span style="color:#89DDFF;">;</span></span></code></pre></div><h3 id="跨站点请求伪造-csrf" tabindex="-1">跨站点请求伪造（CSRF） <a class="header-anchor" href="#跨站点请求伪造-csrf" aria-label="Permalink to “跨站点请求伪造（CSRF）”">​</a></h3><p>攻击者诱导已登录用户在不知情的情况下向目标站点发送请求，冒用其身份完成操作。</p><h3 id="sql-注入" tabindex="-1">SQL 注入 <a class="header-anchor" href="#sql-注入" aria-label="Permalink to “SQL 注入”">​</a></h3><p>攻击者通过拼接恶意 SQL 片段，绕过身份验证或直接操作数据库。</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;">// 危险：字符串拼接 SQL</span></span>
<span class="line"><span style="color:#C792EA;">const</span><span style="color:#BABED8;"> sql </span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;"> \`</span><span style="color:#C3E88D;">SELECT * FROM users WHERE name = &#39;</span><span style="color:#89DDFF;">\${</span><span style="color:#BABED8;">name</span><span style="color:#89DDFF;">}</span><span style="color:#C3E88D;">&#39;</span><span style="color:#89DDFF;">\`</span><span style="color:#89DDFF;">;</span></span></code></pre></div><h3 id="拒绝服务攻击-ddos" tabindex="-1">拒绝服务攻击（DDoS） <a class="header-anchor" href="#拒绝服务攻击-ddos" aria-label="Permalink to “拒绝服务攻击（DDoS）”">​</a></h3><p>攻击者控制大量主机向目标服务器发送海量请求，使其无法正常服务。</p><h2 id="安全设计原则" tabindex="-1">安全设计原则 <a class="header-anchor" href="#安全设计原则" aria-label="Permalink to “安全设计原则”">​</a></h2><ol><li><strong>最小权限原则</strong>：系统组件仅拥有完成任务所需的最低权限。</li><li><strong>纵深防御</strong>：在多个层面部署安全措施，单一防线失效不至于全局崩溃。</li><li><strong>默认安全</strong>：默认配置应当是安全的，而非方便的。</li><li><strong>永不信任输入</strong>：所有来自用户的数据都必须经过校验与清洗。</li><li><strong>保持更新</strong>：及时修补依赖与框架的安全漏洞。</li></ol><h2 id="防御总览" tabindex="-1">防御总览 <a class="header-anchor" href="#防御总览" aria-label="Permalink to “防御总览”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 启用 HTTPS</span></span>
<span class="line"><span style="color:#FFCB6B;">server</span><span style="color:#C3E88D;"> {</span></span>
<span class="line"><span style="color:#FFCB6B;">    listen</span><span style="color:#F78C6C;"> 443</span><span style="color:#C3E88D;"> ssl</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#FFCB6B;">    ssl_certificate</span><span style="color:#C3E88D;">     /path/to/cert.pem</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#FFCB6B;">    ssl_certificate_key</span><span style="color:#C3E88D;"> /path/to/key.pem</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#BABED8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 设置安全响应头</span></span>
<span class="line"><span style="color:#FFCB6B;">add_header</span><span style="color:#C3E88D;"> X-Frame-Options</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">SAMEORIGIN</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#FFCB6B;">add_header</span><span style="color:#C3E88D;"> X-Content-Type-Options</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">nosniff</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#FFCB6B;">add_header</span><span style="color:#C3E88D;"> Content-Security-Policy</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">default-src &#39;self&#39;</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">;</span></span></code></pre></div><p>Web 安全是一个持续演进的过程，没有绝对安全的系统。开发者应结合 OWASP Top 10 定期审计应用，将安全意识融入开发流程的每个环节。</p>`,22)])])}const F=s(t,[["render",o]]);export{D as __pageData,F as default};
